const rows = $input.all();

if (rows.length === 0) {
  return [
    {
      json: {
        totalRows: 0,
        columns: 0,
        missingValues: 0,
        duplicateRows: 0,
        completeness: 100,
        qualityScore: 100
      }
    }
  ];
}

const totalRows = rows.length;
const columnNames = Object.keys(rows[0].json);
const totalColumns = columnNames.length;

// ------------------------------------
// 1. Count ALL missing values
// ------------------------------------
let missingValues = 0;

for (const row of rows) {
  for (const column of columnNames) {
    const value = row.json[column];

    if (
      value === null ||
      value === undefined ||
      value === ''
    ) {
      missingValues++;
    }
  }
}

// ------------------------------------
// 2. Find duplicate rows
// ------------------------------------
const seen = new Set();
let duplicateRows = 0;

for (const row of rows) {
  const rowString = JSON.stringify(row.json);

  if (seen.has(rowString)) {
    duplicateRows++;
  } else {
    seen.add(rowString);
  }
}

// ------------------------------------
// 3. Calculate completeness
// ------------------------------------
const totalCells = totalRows * totalColumns;

const completeness = totalCells === 0
  ? 100
  : ((totalCells - missingValues) / totalCells) * 100;

// ------------------------------------
// 4. Calculate quality score
// ------------------------------------
// Missing values and duplicates both affect quality.

const missingPenalty = totalCells === 0
  ? 0
  : (missingValues / totalCells) * 100;

const duplicatePenalty = totalRows === 0
  ? 0
  : (duplicateRows / totalRows) * 100;

const qualityScore = Math.max(
  0,
  100 - missingPenalty - duplicatePenalty
);

return [
  {
    json: {
      totalRows,
      columns: totalColumns,
      missingValues,
      duplicateRows,
      completeness: Number(completeness.toFixed(2)),
      qualityScore: Number(qualityScore.toFixed(2))
    }
  }
];

const rows = $input.all();

if (rows.length === 0) {
  return [];
}

const columns = Object.keys(rows[0].json);

const profile = columns.map(column => {
  const values = rows.map(item => item.json[column]);

  // Values that are actually present
  const nonEmptyValues = values.filter(
    value =>
      value !== null &&
      value !== undefined &&
      value !== ''
  );

  const missing = values.length - nonEmptyValues.length;

  // ------------------------------------
  // Unique values
  // ------------------------------------
  const unique = new Set(
    nonEmptyValues.map(value => String(value))
  ).size;

  // ------------------------------------
  // Detect numeric values
  // ------------------------------------
  const numericValues = nonEmptyValues.filter(value => {
    const number = Number(String(value).trim());
    return !isNaN(number) && isFinite(number);
  });

  const numericRatio =
    nonEmptyValues.length === 0
      ? 0
      : numericValues.length / nonEmptyValues.length;

  // ------------------------------------
  // Detect basic column type
  // ------------------------------------
  let detectedType = 'Text';

  // If at least 80% of non-empty values
  // are numeric, treat the column as Number.
  if (numericRatio >= 0.8) {
    detectedType = 'Number';
  }

  // ------------------------------------
  // Calculate validity
  // ------------------------------------
  let validValues;
  let invalidValues;

  if (detectedType === 'Number') {
    validValues = numericValues.length;
    invalidValues = nonEmptyValues.length - validValues;
  } else {
    // For Text columns, every non-empty value
    // is considered structurally valid.
    validValues = nonEmptyValues.length;
    invalidValues = 0;
  }

  const validity =
    nonEmptyValues.length === 0
      ? 100
      : (validValues / nonEmptyValues.length) * 100;

  // ------------------------------------
  // Calculate completeness
  // ------------------------------------
  const completeness =
    values.length === 0
      ? 100
      : ((values.length - missing) / values.length) * 100;

  return {
    column,
    detectedType,

    totalValues: values.length,

    missingValues: missing,

    uniqueValues: unique,

    validValues,

    invalidValues,

    completeness: Number(completeness.toFixed(2)),

    validity: Number(validity.toFixed(2))
  };
});

return profile.map(item => ({
  json: item
}));

const items = $input.all();

let summary = {};
let columns = [];

// ------------------------------------
// Collect overall metrics and columns
// ------------------------------------
for (const item of items) {
  const data = item.json;

  // Overall metrics
  if (data.totalRows !== undefined) {
    summary = {
      totalRows: data.totalRows,
      totalColumns: data.columns,
      missingValues: data.missingValues,
      duplicateRows: data.duplicateRows,
      completeness: data.completeness
    };
  }

  // Column profiling
  if (data.column !== undefined) {
    columns.push({
      column: data.column,
      detectedType: data.detectedType,
      totalValues: data.totalValues,
      missingValues: data.missingValues,
      uniqueValues: data.uniqueValues,
      validValues: data.validValues,
      invalidValues: data.invalidValues,
      completeness: data.completeness,
      validity: data.validity
    });
  }
}

// ------------------------------------
// Calculate overall validity
// ------------------------------------
const validity =
  columns.length === 0
    ? 100
    : columns.reduce(
        (sum, column) => sum + column.validity,
        0
      ) / columns.length;

// ------------------------------------
// Calculate duplicate health
// ------------------------------------
const duplicateHealth =
  summary.totalRows === 0
    ? 100
    : (
        (summary.totalRows - summary.duplicateRows) /
        summary.totalRows
      ) * 100;

// ------------------------------------
// Calculate overall quality score
// ------------------------------------
// Equal weight for all 3 dimensions
const qualityScore =
  (
    summary.completeness +
    validity +
    duplicateHealth
  ) / 3;

// ------------------------------------
// Final result
// ------------------------------------
summary = {
  ...summary,

  validity: Number(validity.toFixed(2)),

  duplicateHealth: Number(
    duplicateHealth.toFixed(2)
  ),

  qualityScore: Number(
    qualityScore.toFixed(2)
  )
};

return [
  {
    json: {
      summary,
      columns
    }
  }
];

